/* ---------- 7. Mis poses de cuerpo entero (BV-4, D4) ----------
   js/shv-bubble.js 1.6.0 les saca el fondo con el recorte del kit y las deja en body como --svk-p-<pose>
   con la clase svk-p-<pose>: hasta que no están listas estas reglas no aplican (nunca un rectángulo negro).
   Inicio («Shiruvana te guía», también el saludo sin Key): saluda, en lugar del avatar redondo.
   Pantallas vacías de verdad (no las de filtros ni las que cargan): la cola de la Armería, Cuentas sin
   cuentas y Compras fijadas sin nada fijado: pensando. Nunca en saldos, tablas ni navegación. La pose va
   al costado, con su lugar propio (padding), así no tapa el texto. */
:root:is([data-theme="gato"],:not([data-theme])) body.svk-p-saluda #welcomePanel [data-shv-place="welcome"] {
  grid-template-columns: minmax(0, 1fr); min-height: 270px; padding-right: 200px;
  background-image: var(--svk-p-saluda); background-repeat: no-repeat; background-position: right 16px bottom 0; background-size: 170px auto;
}
:root:is([data-theme="gato"],:not([data-theme])) body.svk-p-saluda #welcomePanel [data-shv-place="welcome"] > .shv-voice__avatar { display: none; }
:root:is([data-theme="gato"],:not([data-theme])) body.svk-p-pensando :is(.arm-qview > .arm-empty, .cv-empty, div.wvp-empty) {
  min-height: 210px; padding-right: 170px; text-align: left;
  background-image: var(--svk-p-pensando); background-repeat: no-repeat; background-position: right 12px bottom 0; background-size: 140px auto;
}
